import 'package:flutter/material.dart';
import '../../core/api_client.dart';

class AiConfigurationPage extends StatefulWidget{const AiConfigurationPage({super.key,required this.api});final PosApiClient api;@override State<AiConfigurationPage> createState()=>_AiConfigurationPageState();}
class _AiConfigurationPageState extends State<AiConfigurationPage>{String provider='auto';final model=TextEditingController();final key=TextEditingController();final base=TextEditingController();List<dynamic> discovered=[];String? status;bool saving=false;@override void dispose(){model.dispose();key.dispose();base.dispose();super.dispose();}
 Future<void> discover()async{try{final d=await widget.api.discoverAiProviders();if(mounted)setState(()=>discovered=d);}catch(e){setState(()=>status=e.toString());}}
 Future<void> save()async{setState(()=>saving=true);try{await widget.api.aiConfiguration(provider:provider,model:model.text,apiKey:key.text,baseUrl:base.text);status='Saved. Automatic mode will use a free local server when available.';}catch(e){status=e.toString();}if(mounted)setState(()=>saving=false);}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('AI Configuration')),body:ListView(padding:const EdgeInsets.all(16),children:[DropdownButtonFormField<String>(value:provider,decoration:const InputDecoration(labelText:'Provider'),items:const['auto','openai','ollama','lmstudio','llamacpp'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>provider=v??'auto')),TextField(controller:model,decoration:const InputDecoration(labelText:'Model')),TextField(controller:key,obscureText:true,decoration:const InputDecoration(labelText:'Purchased API key (optional for local/free AI)')),TextField(controller:base,decoration:const InputDecoration(labelText:'Custom base URL (optional)')),const SizedBox(height:12),Row(children:[Expanded(child:FilledButton.icon(onPressed:saving?null:save,icon:const Icon(Icons.save),label:const Text('Save'))),const SizedBox(width:8),OutlinedButton(onPressed:discover,child:const Text('Detect Free AI'))]),if(discovered.isNotEmpty)...[const SizedBox(height:16),const Text('Detected providers',style:TextStyle(fontWeight:FontWeight.bold)),...discovered.map((x)=>ListTile(title:Text('${x['provider']} • ${x['model']}'),subtitle:Text('${x['baseUrl']} • ${x['status']}'),onTap:(){setState((){provider='${x['provider']}';model.text='${x['model']}';base.text='${x['baseUrl']}';});}))],if(status!=null)Padding(padding:const EdgeInsets.only(top:16),child:Text(status!))]));}
